WITH users_in_india AS (
  SELECT Id FROM users WHERE Location LIKE '%India%'
),
users_yearling_before_2014 AS (
  SELECT DISTINCT UserId FROM badges
  WHERE Name = 'Yearling' AND Date < '2014-01-01'
)
SELECT COUNT(*) AS user_count
FROM users_in_india u
JOIN users_yearling_before_2014 b ON u.Id = b.UserId;

