WITH chlorine_atoms AS (
  SELECT atom_id FROM atom WHERE element = 'Cl'
), bonded_atoms AS (
  SELECT c.atom_id AS bonded_atom FROM connected c JOIN chlorine_atoms cl ON c.atom_id2 = cl.atom_id
  UNION ALL
  SELECT c.atom_id2 AS bonded_atom FROM connected c JOIN chlorine_atoms cl ON c.atom_id = cl.atom_id
)
SELECT COUNT(DISTINCT bonded_atom) AS count_bonded_to_chlorine FROM bonded_atoms;
